def solve(n):
    # c[r] = количество чисел от 1 до n с остатком r по модулю 7
    c = [0, 0, 0, 0, 0, 0, 0]
    for k in range(1, n + 1):
        c[k % 7] += 1
    # Минимальное число 'плохих' соседних пар = минимальное число отрезков,
    # в каждом из которых соседние пары дают сумму, кратную 7
    S = 0
    if c[0] > 0:
        S += 1
    for a in range(1, 4):
        b = 7 - a
        if c[a] + c[b] > 0:
            S += max(1, abs(c[a] - c[b]))
    return n - S
